export type Service = {
  slug: string;
  name: string;
  h1: string;
  title: string;
  description: string;
  icon: string;
  short: string;
  priceFrom: number;
  /** ราคาสูงสุดในตารางของบริการนี้ ใช้กับ priceSpecification ใน schema
   *  เพราะ price ตัวเดียวสื่อว่าเป็นราคาตายตัว ซึ่งไม่ตรงกับที่หน้าเว็บบอก */
  priceTo?: number;
  /** คำอธิบายราคาแบบสั้นสำหรับ schema กรณีที่ตัวเลขเดียวสื่อความไม่ครบ */
  priceNote?: string;
  /** ระยะเวลาทำงานแบบ ISO 8601 ใส่เฉพาะบริการที่หน้าเว็บระบุเวลาไว้จริง
   *  บริการที่ไม่ได้ระบุ ปล่อยว่างไว้ ห้ามเดาใส่ schema */
  durationISO?: string;
  priceLabel: string;
  intro: string;
  bullets: string[];
  steps: { title: string; detail: string }[];
  faqs: { q: string; a: string }[];
};

